/* Literal complete SEP-04.2/03 captures; no reconstructed route model. */
typedef struct { unsigned unit,tick,visit; uint32_t before[5],after[5]; int box[4];
    uint32_t random_before[2],random_after[2],endpoint[2]; int admission; } crowdVisit_t;
typedef struct { unsigned unit,tick,visit,before,after,result; uint32_t random_before[2],random_after[2]; } crowdRetry_t;
static char const crowd_script[]=
    "globals\n"
    " unit array udg_SepU\n"
    " integer udg_SepTick=0\n"
    "endglobals\n"
    "function SepRec takes integer i returns nothing\n"
    " local unit u=udg_SepU[i]\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=s i=\"+I2S(i)+\" x=\"+R2SW(GetUnitX(u),1,4)+\" y=\"+R2SW(GetUnitY(u),1,4)+\" o=\"+I2S(GetUnitCurrentOrder(u))+\" p=\"+I2S(GetPlayerId(GetOwningPlayer(u))))\n"
    " set u=null\n"
    "endfunction\n"
    "function SepMake takes integer i,integer p,integer rc,real x,real y returns nothing\n"
    " set udg_SepU[i]=CreateUnit(Player(p),rc,x,y,0.0)\n"
    " call SetUnitX(udg_SepU[i],x)\n"
    " call SetUnitY(udg_SepU[i],y)\n"
    " call SetUnitAcquireRange(udg_SepU[i],0.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=unit i=\"+I2S(i)+\" code=\"+I2S(rc)+\" p=\"+I2S(p)+\" h=\"+I2S(GetHandleId(udg_SepU[i]))+\" x=\"+R2SW(GetUnitX(udg_SepU[i]),1,4)+\" y=\"+R2SW(GetUnitY(udg_SepU[i]),1,4))\n"
    "endfunction\n"
    "function SepStep takes nothing returns nothing\n"
    " local integer i\n"
    " set udg_SepTick=udg_SepTick+1\n"
    " if udg_SepTick==2 then\n"
    " call Preload(\"PATHSEP tick=2 label=phase first=0 last=9\")\n"
    " call SepMake(0,0,'hS00',1094.4000,1008.0000)\n"
    " call SepMake(1,1,'hS00',1106.4000,1008.0000)\n"
    " call SepMake(2,0,'hSC1',1118.4000,1008.0000)\n"
    " call SepMake(3,0,'hSC2',1130.4000,1008.0000)\n"
    " call SepMake(4,0,'hSR1',1094.4000,1020.0000)\n"
    " call SepMake(5,0,'hSR2',1106.4000,1020.0000)\n"
    " call SepMake(6,0,'hS02',1118.4000,1020.0000)\n"
    " call SepMake(7,1,'hS04',1130.4000,1020.0000)\n"
    " call SepMake(8,0,'hSD0',1094.4000,1032.0000)\n"
    " call SepMake(9,1,'hSC1',1106.4000,1032.0000)\n"
    " endif\n"
    " if udg_SepTick==122 then\n"
    " call IssuePointOrder(udg_SepU[0],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[1],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[2],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[3],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[4],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[5],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[6],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[7],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[8],\"move\",1008.0,1040.0)\n"
    " call IssuePointOrder(udg_SepU[9],\"move\",1008.0,1040.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=action cluster=0\")\n"
    " endif\n"
    " if udg_SepTick>2 and udg_SepTick<=302 and (udg_SepTick/2)*2==udg_SepTick then\n"
    " set i=0\n"
    " loop\n"
    " exitwhen i>9\n"
    " call SepRec(i)\n"
    " set i=i+1\n"
    " endloop\n"
    " endif\n"
    " if udg_SepTick==303 then\n"
    " set i=0\n"
    " loop\n"
    " exitwhen i>9\n"
    " call RemoveUnit(udg_SepU[i])\n"
    " set i=i+1\n"
    " endloop\n"
    " call Preload(\"PATHSEP tick=303 label=phase_end\")\n"
    " endif\n"
    " if udg_SepTick==312 then\n"
    " call Preload(\"PATHSEP tick=312 label=complete\")\n"
    "\n"
    " call DestroyTimer(GetExpiredTimer())\n"
    " endif\n"
    "endfunction\n"
    "function PathProbeInit takes nothing returns nothing\n"
    " call PreloadGenClear()\n"
    " call PreloadGenStart()\n"
    " call Preload(\"PATHSEP tick=0 label=start_crowd\")\n"
    " call FogEnable(false)\n"
    " call FogMaskEnable(false)\n"
    " call TimerStart(CreateTimer(),0.05,true,function SepStep)\n"
    "endfunction\n"
    "\n"
    "function main takes nothing returns nothing\n"
    " call PathProbeInit()\n"
    "endfunction\n"
;
