static char const ground_script[]=
    "globals\n"
    " unit array udg_SepU\n"
    " integer udg_SepTick=0\n"
    "endglobals\n"
    "function SepRec takes integer i returns nothing\n"
    " local unit u=udg_SepU[i]\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=s i=\"+I2S(i)+\" x=\"+R2SW(GetUnitX(u),1,4)+\" y=\"+R2SW(GetUnitY(u),1,4)+\" o=\"+I2S(GetUnitCurrentOrder(u))+\" p=\"+I2S(GetPlayerId(GetOwningPlayer(u))))\n"
    " set u=null\n"
    "endfunction\n"
    "function SepMake takes integer i,integer p,integer rc,real x,real y returns nothing\n"
    " set udg_SepU[i]=CreateUnit(Player(p),rc,x,y,0.0)\n"
    " call SetUnitX(udg_SepU[i],x)\n"
    " call SetUnitY(udg_SepU[i],y)\n"
    " call SetUnitAcquireRange(udg_SepU[i],0.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=unit i=\"+I2S(i)+\" code=\"+I2S(rc)+\" p=\"+I2S(p)+\" h=\"+I2S(GetHandleId(udg_SepU[i]))+\" x=\"+R2SW(GetUnitX(udg_SepU[i]),1,4)+\" y=\"+R2SW(GetUnitY(udg_SepU[i]),1,4))\n"
    "endfunction\n"
    "function SepStep takes nothing returns nothing\n"
    " local integer i\n"
    " set udg_SepTick=udg_SepTick+1\n"
    " if udg_SepTick==2 then\n"
    " call Preload(\"PATHSEP tick=2 label=phase first=0 last=7\")\n"
    " call SepMake(0,0,'hSC1',256.0000,1552.0000)\n"
    " call SepMake(1,0,'hSC1',296.0000,1552.0000)\n"
    " call SepMake(2,0,'hSC1',336.0000,1552.0000)\n"
    " call SepMake(3,0,'hSC1',376.0000,1552.0000)\n"
    " call SepMake(4,0,'hSD1',256.0000,400.0000)\n"
    " call SepMake(5,0,'hSD1',296.0000,400.0000)\n"
    " call SepMake(6,0,'hSD1',336.0000,400.0000)\n"
    " call SepMake(7,0,'hSD1',376.0000,400.0000)\n"
    " endif\n"
    " if udg_SepTick==22 then\n"
    " call IssuePointOrder(udg_SepU[0],\"move\",720.0,1552.0)\n"
    " call IssuePointOrder(udg_SepU[1],\"move\",720.0,1552.0)\n"
    " call IssuePointOrder(udg_SepU[2],\"move\",720.0,1552.0)\n"
    " call IssuePointOrder(udg_SepU[3],\"move\",720.0,1552.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=action cluster=0\")\n"
    " call IssuePointOrder(udg_SepU[4],\"move\",720.0,400.0)\n"
    " call IssuePointOrder(udg_SepU[5],\"move\",720.0,400.0)\n"
    " call IssuePointOrder(udg_SepU[6],\"move\",720.0,400.0)\n"
    " call IssuePointOrder(udg_SepU[7],\"move\",720.0,400.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=action cluster=1\")\n"
    " endif\n"
    " if udg_SepTick==202 then\n"
    " call IssuePointOrder(udg_SepU[0],\"move\",1552.0,1616.0)\n"
    " call IssuePointOrder(udg_SepU[1],\"move\",1552.0,1616.0)\n"
    " call IssuePointOrder(udg_SepU[2],\"move\",1552.0,1616.0)\n"
    " call IssuePointOrder(udg_SepU[3],\"move\",1552.0,1616.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=action cluster=0\")\n"
    " call IssuePointOrder(udg_SepU[4],\"move\",1552.0,464.0)\n"
    " call IssuePointOrder(udg_SepU[5],\"move\",1552.0,464.0)\n"
    " call IssuePointOrder(udg_SepU[6],\"move\",1552.0,464.0)\n"
    " call IssuePointOrder(udg_SepU[7],\"move\",1552.0,464.0)\n"
    " call Preload(\"PATHSEP tick=\"+I2S(udg_SepTick)+\" label=action cluster=1\")\n"
    " endif\n"
    " if udg_SepTick>2 and udg_SepTick<=402 and (udg_SepTick/2)*2==udg_SepTick then\n"
    " set i=0\n"
    " loop\n"
    " exitwhen i>7\n"
    " call SepRec(i)\n"
    " set i=i+1\n"
    " endloop\n"
    " endif\n"
    " if udg_SepTick==403 then\n"
    " set i=0\n"
    " loop\n"
    " exitwhen i>7\n"
    " call RemoveUnit(udg_SepU[i])\n"
    " set i=i+1\n"
    " endloop\n"
    " call Preload(\"PATHSEP tick=403 label=phase_end\")\n"
    " endif\n"
    " if udg_SepTick==412 then\n"
    " call Preload(\"PATHSEP tick=412 label=complete\")\n"
    "\n"
    " call DestroyTimer(GetExpiredTimer())\n"
    " endif\n"
    "endfunction\n"
    "function PathProbeInit takes nothing returns nothing\n"
    " call PreloadGenClear()\n"
    " call PreloadGenStart()\n"
    " call Preload(\"PATHSEP tick=0 label=start_ground\")\n"
    " call FogEnable(false)\n"
    " call FogMaskEnable(false)\n"
    " call TimerStart(CreateTimer(),0.05,true,function SepStep)\n"
    "endfunction\n"
    "\n"
    "function main takes nothing returns nothing\n"
    " call PathProbeInit()\n"
    "endfunction\n"
;
